import { MODULE_ID } from '../constants.js';
import { escapeHTML, localize, sluggify } from '../helpers/utility.js';
import { TRADITIONS, classRules, detectTradition, findClassEntry, loadSpellcastingData } from './spellcasting.js';
import { addInnateSpells, innateGrantsFor } from './innateSpells.js';

let focusData = null;

/** Focus spells granted by feats and class features, generated by scripts/build-focus-spells.mjs */
export const loadFocusData = async () => {
  if (focusData) return focusData;
  try {
    focusData = await foundry.utils.fetchJsonWithTimeout(`modules/${MODULE_ID}/src/data/focusSpells.json`);
  } catch (error) {
    console.error(`${MODULE_ID} | Failed to load focus spell data`, error);
    focusData = { grants: {}, spells: {}, domains: {} };
  }
  return focusData;
};

/** For tests: use data loaded some other way */
export const setFocusData = (data) => {
  focusData = data;
};

const slugOf = (item) => item.slug ?? sluggify(item.name);
const selections = (item) => item.flags?.[game.system.id]?.rulesSelections ?? {};

/** Domains whose initial spell the actor has, from every Domain Initiate–style choice it made */
const ownedDomains = (actor) => {
  const domains = new Set();
  for (const item of actor.items) {
    const chosen = selections(item);
    for (const key of ['domainInitiate', 'deitysDomain', 'expandedDomainInitiate']) {
      if (typeof chosen[key] === 'string') domains.add(chosen[key]);
    }
  }
  return [...domains];
};

/** Whether an option's condition holds (devotion spells depend on the deity's divine font) */
const conditionHolds = (actor, condition) => {
  if (!condition) return true;
  const font = condition.match(/^deity:primary:font:(\w+)$/)?.[1];
  if (!font) return true;
  const fonts = actor.deity?.system?.font ?? [];
  return !fonts.length || fonts.includes(font);
};

const domainSpells = (domains, tier) =>
  domains.flatMap((d) => focusData.domains?.[d]?.[tier] ?? []);

/** Focus spells (uuids) matching a pick filter: traits all present, the given rank */
const filterSpells = (filter) =>
  Object.entries(focusData.spells ?? {})
    .filter(([, s]) => (filter.traits ?? []).every((t) => s.traits.includes(t)))
    .filter(([, s]) => filter.rank === undefined || (s.cantrip ? 0 : s.rank) === filter.rank)
    .map(([uuid]) => uuid);

/**
 * What a newly gained feat or feature gives: `{ fixed: uuid[] }` for spells that follow from the
 * item (and the choices PF2e already asked for), `{ options: uuid[], count }` for a pick, or null when
 * the module can't tell (the reminder whisper still mentions it).
 */
export const resolveGrant = (actor, item, grant) => {
  switch (grant.kind) {
    case 'fixed':
      return { fixed: grant.spells ?? [] };
    case 'choice': {
      const choice = grant.choice ?? {};
      if (choice.type === 'flag') {
        const value = selections(item)[choice.flag];
        if (typeof value !== 'string') return null;
        return { fixed: choice.table === 'domains' ? domainSpells([value], choice.tier) : (choice.map?.[value] ?? []) };
      }
      if (choice.type === 'feature') {
        const owned = actor.items.find((i) => choice.map?.[slugOf(i)]);
        return owned ? { fixed: choice.map[slugOf(owned)] } : null;
      }
      return null;
    }
    case 'pick': {
      const pick = grant.pick ?? {};
      let options = [];
      if (pick.options) {
        options = pick.options.filter((uuid) => conditionHolds(actor, pick.conditions?.[uuid]));
        if (pick.filter) options = [...new Set([...options, ...filterSpells(pick.filter)])];
      } else if (pick.from === 'domains') {
        const domains =
          pick.scope === 'owned'
            ? ownedDomains(actor)
            : pick.scope === 'any'
              ? Object.keys(focusData.domains ?? {})
              : pick.scope === 'deity-alternate'
                ? (actor.deity?.system?.domains?.alternate ?? [])
                : [];
        options = domainSpells(domains, pick.tier ?? 'initial');
      }
      return options.length ? { options, count: pick.count ?? 1 } : null;
    }
    default:
      return null;
  }
};

/** The tradition and attribute a grant's spells are cast with; tradition may be null (the player picks) */
const castingFor = (actor, grant) => {
  const cls = actor.class;
  const slug = cls ? (cls.slug ?? sluggify(cls.name)) : null;
  let tradition = TRADITIONS.includes(grant.tradition) ? grant.tradition : null;
  if (grant.tradition === 'class' && slug) {
    const rules = classRules(slug);
    const entry = rules ? findClassEntry(actor, rules, slug)?.entry : null;
    tradition = entry?.system?.tradition?.value || (rules ? detectTradition(actor, rules, slug) : null);
  }
  const attribute =
    grant.ability && grant.ability !== 'class' ? grant.ability : (cls?.system?.keyAbility?.selected ?? null);
  return { tradition, attribute };
};

/**
 * Focus spells the new items give, grouped by source, leaving out spells the actor already has.
 * @param {Actor} actor
 * @param {Item[]} items items added by the build or level-up (including those PF2e granted)
 */
export const focusGrantsFor = async (actor, items) => {
  await Promise.all([loadFocusData(), loadSpellcastingData()]);
  const owned = new Set(actor.itemTypes.spell.map((s) => s.sourceId).filter(Boolean));
  const groups = [];
  for (const item of items) {
    if (!['feat', 'heritage'].includes(item.type)) continue;
    const grant = focusData.grants?.[slugOf(item)];
    if (!grant) continue;
    const resolved = resolveGrant(actor, item, grant);
    if (!resolved) continue;
    const fresh = (list) => list.filter((uuid) => !owned.has(uuid) && focusData.spells?.[uuid]);
    const fixed = fresh(resolved.fixed ?? []);
    const options = fresh(resolved.options ?? []);
    if (!fixed.length && !options.length) continue;
    groups.push({
      key: item.id,
      source: item.name,
      grant,
      fixed,
      options,
      count: Math.min(resolved.count ?? 0, options.length),
      ...castingFor(actor, grant)
    });
  }
  return groups;
};

const spellLabel = (uuid) => {
  const s = focusData.spells?.[uuid];
  if (!s) return uuid;
  const rank = s.cantrip ? localize('spells.cantrip') : localize('spells.rankShort', { rank: s.rank });
  return `${escapeHTML(s.name)} <span class="lvl-focus-rank">${rank}</span>`;
};

/** Which spells the dialog offers: focus, innate or both; picks its title, intro and button */
const dialogKind = (groups) => {
  const innate = groups.some((g) => g.kind === 'innate');
  const focus = groups.some((g) => g.kind !== 'innate');
  return innate && focus ? 'mixed' : innate ? 'innate' : 'focus';
};

const DIALOG_TEXT = {
  focus: { title: 'focus.title', intro: 'focus.intro', add: 'focus.add' },
  innate: { title: 'innate.title', intro: 'innate.intro', add: 'innate.add' },
  mixed: { title: 'innate.titleMixed', intro: 'innate.introMixed', add: 'innate.add' }
};

/** Dialog content: one block per source, fixed spells ticked, picks as radios or checkboxes */
const dialogContent = (groups) => {
  // Innate groups carry their own labels (rank as cast, not the spell's own)
  const label = (group, uuid) => group.labels?.[uuid] ?? spellLabel(uuid);
  const traditionSelect = (group) =>
    group.tradition
      ? ''
      : `<label class="lvl-focus-tradition">${localize('focus.tradition')}
          <select name="tradition-${group.key}">${TRADITIONS.map(
            (t) => `<option value="${t}">${escapeHTML(game.i18n.localize(CONFIG.PF2E.magicTraditions?.[t] ?? t))}</option>`
          ).join('')}</select></label>`;
  const blocks = groups.map((group) => {
    const fixed = group.fixed
      .map(
        (uuid) =>
          `<label class="lvl-focus-option"><input type="checkbox" name="spell-${group.key}" value="${uuid}" checked> ${label(group, uuid)}</label>`
      )
      .join('');
    const type = group.count === 1 ? 'radio' : 'checkbox';
    const options = group.options
      .map(
        (uuid, i) =>
          `<label class="lvl-focus-option"><input type="${type}" name="pick-${group.key}" value="${uuid}" ${
            i < group.count && type === 'radio' ? 'checked' : ''
          }> ${label(group, uuid)}</label>`
      )
      .join('');
    const pickHint = group.options.length
      ? `<p class="hint">${localize('focus.pickHint', { count: group.count })}</p>`
      : '';
    // Grants matched from the feat's wording (not checked by hand) carry a tag and the sentence itself
    const unchecked = group.grant.confidence === 'heuristic';
    const tag = unchecked
      ? ` <span class="lvl-focus-check" data-tooltip="${escapeHTML(localize('focus.checkTooltip'))}">${localize('focus.check')}</span>`
      : '';
    const quote =
      unchecked && group.grant.note
        ? `<p class="lvl-focus-quote">${localize('focus.checkHint')} <q>${escapeHTML(group.grant.note)}</q></p>`
        : '';
    const kind = group.tag ? ` <span class="lvl-focus-kind">${escapeHTML(group.tag)}</span>` : '';
    return `<fieldset class="lvl-focus-group${unchecked ? ' unchecked' : ''}"><legend>${escapeHTML(group.source)}${kind}${tag}</legend>${quote}${fixed}${pickHint}${options}${traditionSelect(group)}</fieldset>`;
  });
  const anyUnchecked = groups.some((g) => g.grant.confidence === 'heuristic');
  const text = localize(DIALOG_TEXT[dialogKind(groups)].intro);
  const intro = anyUnchecked ? `${text} ${localize('focus.introCheck')}` : text;
  return `<p>${intro}</p>${blocks.join('')}`;
};

/**
 * Ask which focus spells to add. Resolves to `[{ group, uuids, tradition }]`, or null when skipped.
 */
export const askFocusSpells = async (groups, { windowId } = {}) => {
  if (!groups.length) return null;
  const text = DIALOG_TEXT[dialogKind(groups)];
  return foundry.applications.api.DialogV2.wait({
    window: { title: localize(text.title), icon: 'fa-solid fa-hand-sparkles' },
    classes: [MODULE_ID, 'lvlup-focus-dialog'],
    position: { width: 460 },
    content: dialogContent(groups),
    rejectClose: false,
    modal: true,
    renderOptions: windowId ? { window: { windowId } } : undefined,
    buttons: [
      {
        action: 'add',
        label: localize(text.add),
        icon: 'fa-solid fa-check',
        default: true,
        callback: (event, button) => {
          const form = button.form;
          return groups.map((group) => {
            const checked = (name) =>
              [...form.querySelectorAll(`input[name="${name}"]:checked`)].map((input) => input.value);
            const picks = checked(`pick-${group.key}`).slice(0, Math.max(group.count, 1));
            return {
              group,
              uuids: [...checked(`spell-${group.key}`), ...picks],
              tradition: group.tradition ?? form.querySelector(`[name="tradition-${group.key}"]`)?.value ?? null
            };
          });
        }
      },
      { action: 'skip', label: localize('focus.skip'), icon: 'fa-solid fa-xmark' }
    ]
  }).then((result) => (Array.isArray(result) ? result : null));
};

const entryName = (actor, group) => {
  const classSlug = actor.class ? (actor.class.slug ?? sluggify(actor.class.name)) : null;
  const name =
    group.grant.group === classSlug || !group.grant.group
      ? (actor.class?.name ?? '')
      : group.grant.group.split('-').map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  return localize('focus.entryName', { name }).trim();
};

/**
 * Add the chosen focus spells, each into a focus entry of its tradition (an existing one, or a new
 * one). Returns the created items so the caller can record them for undo.
 */
export const addFocusSpells = async (actor, choices) => {
  const created = [];
  const entries = new Map(
    actor.itemTypes.spellcastingEntry
      .filter((e) => e.system?.prepared?.value === 'focus')
      .map((e) => [e.system?.tradition?.value ?? '', e])
  );
  for (const { group, uuids, tradition } of choices) {
    if (!uuids.length) continue;
    let entry = entries.get(tradition ?? '');
    if (!entry) {
      [entry] = await actor.createEmbeddedDocuments('Item', [
        {
          type: 'spellcastingEntry',
          name: entryName(actor, group),
          system: {
            ability: { value: group.attribute ?? '' },
            tradition: { value: tradition ?? '' },
            prepared: { value: 'focus', flexible: false },
            // Monks and rangers have no spellcasting rank from their class; their focus spells are trained
            proficiency: { slug: '', value: 1 },
            showSlotlessLevels: { value: false }
          },
          flags: { [MODULE_ID]: { focusEntry: group.grant.group ?? true } }
        }
      ]);
      created.push(entry);
      entries.set(tradition ?? '', entry);
    }
    const sources = await Promise.all(
      uuids.map(async (uuid) => {
        const doc = await fromUuid(uuid);
        if (!doc) return null;
        const source = doc.toObject();
        delete source._id;
        delete source.folder;
        delete source.sort;
        delete source.ownership;
        foundry.utils.setProperty(source, '_stats.compendiumSource', doc.uuid);
        source.system.location = { value: entry.id };
        return source;
      })
    );
    created.push(...(await actor.createEmbeddedDocuments('Item', sources.filter(Boolean))));
  }
  return created;
};

/**
 * After a build or level-up: offer the focus and innate spells the new items give and add the chosen
 * ones. Never throws; returns the created items (empty when nothing was added).
 */
export const offerFocusSpells = async (actor, newItems, options = {}) => {
  try {
    const innate = await innateGrantsFor(actor, newItems).catch((error) => {
      console.error(`${MODULE_ID} | Could not read innate spells`, error);
      return [];
    });
    const groups = [...(await focusGrantsFor(actor, newItems)), ...innate];
    const choices = await askFocusSpells(groups, options);
    if (!choices) return { created: [], handled: [] };
    const created = [
      ...(await addFocusSpells(actor, choices.filter((c) => c.group.kind !== 'innate'))),
      ...(await addInnateSpells(actor, choices.filter((c) => c.group.kind === 'innate')))
    ];
    return { created, handled: [...new Set(groups.map((g) => g.source))] };
  } catch (error) {
    console.error(`${MODULE_ID} | Could not add focus spells`, error);
    ui.notifications.warn(localize('focus.failed'));
    return { created: [], handled: [] };
  }
};
